const headers = $input.first().json.headers || {};
const authHeader = headers.authorization || headers.Authorization;
if (!authHeader || typeof authHeader !== 'string') { throw new Error('Unauthorized'); }
const parts = authHeader.split(' ');
if (parts.length < 2 || !parts[1]) { throw new Error('Unauthorized'); }
const tokenParts = parts[1].split('.');
if (tokenParts.length < 2) { throw new Error('Unauthorized'); }
const base64 = tokenParts[1].replace(/-/g, '+').replace(/_/g, '/');
const payload = JSON.parse(Buffer.from(base64, 'base64').toString('utf8'));

const body = $input.first().json.body || {};
const rawMessage = (body.message || '').toString().trim();

// ================= إعدادات قابلة للتعديل =================
// عدد الطلبات المسموح بها لكل معلّم في اليوم الواحد (لحماية باقي المعلمين
// من إن معلم واحد يستهلك كل الحصة المجانية المشتركة)
const dailyLimit = 40;
// أقل عدد ثوانٍ لازم يفصل بين طلبين لكل النظام (كل المعلمين مجتمعين) -
// ده بيحمي حصة Gemini المجانية من تجاوز حد الطلبات بالدقيقة (RPM).
// 5 ثواني = أقصى ~12 طلب/دقيقة للنظام كله. زوّدها لو ظهرت أخطاء 429
// كتير، أو قلّلها لو عدد المعلمين قليل وحصتك المجانية بتسمح بأكتر
// (تقدر تتابع حدودك الفعلية من https://aistudio.google.com/usage)
const minIntervalSeconds = 5;
// أقصى طول لرسالة المعلم (حماية من إساءة الاستخدام واستهلاك حصة زيادة)
const maxMessageLength = 600;
// عدد آخر الرسائل اللي المساعد "بيفتكرها" من نفس الطالب (10 من المعلم
// + 10 من المساعد تقريبًا)
const memoryLimit = 20;
// اسم موديل Gemini - اختار أخف/أرخص موديل مجاني متاح لحسابك من
// https://aistudio.google.com (الأسماء والحدود المجانية بتتغيّر بمرور
// الوقت، تأكد من الاسم الصحيح قبل التفعيل)
const geminiModel = 'gemini-2.0-flash-lite';

let validationError = null;
if (!body.student_id) {
    validationError = 'رقم الطالب مطلوب';
} else if (!rawMessage) {
    validationError = 'من فضلك اكتب رسالة';
} else if (rawMessage.length > maxMessageLength) {
    validationError = `الرسالة طويلة جدًا (الحد الأقصى ${maxMessageLength} حرف)`;
}

return {
    teacherId: payload.sub,
    studentId: body.student_id || null,
    message: rawMessage,
    isValid: validationError === null,
    validationError,
    dailyLimit,
    minIntervalSeconds,
    maxMessageLength,
    memoryLimit,
    geminiModel
};

