const config = $('Decode JWT & Config').item.json;
const student = $('Get Student Context').item.json;
const memoryItems = $('Get Chat Memory').all().map(i => i.json).filter(m => m.role && m.content);
// الرسائل راجعة من الأحدث للأقدم - لازم نرتبها زمنيًا (الأقدم أولًا) قبل
// ما نبنيها كسياق محادثة لـ Gemini
memoryItems.reverse();

const lessons = Array.isArray(student.recent_lessons) ? student.recent_lessons : [];
const notes = Array.isArray(student.notes) ? student.notes : [];

const lessonsText = lessons.length
    ? lessons.map((l) => {
        const date = (l.lesson_date || '').toString().substring(0, 10);
        const parts = [];
        if (l.lesson_content) parts.push(`المحتوى: ${l.lesson_content}`);
        if (l.memorization) parts.push(`الحفظ: ${l.memorization}`);
        if (l.recitation) parts.push(`الأداء الشفهي: ${l.recitation}`);
        if (l.performance) parts.push(`الأداء العام: ${l.performance}`);
        if (l.notes) parts.push(`ملاحظات: ${l.notes}`);
        if (l.next_assignment) parts.push(`المهمة القادمة: ${l.next_assignment}`);
        if (l.homework) parts.push(`الواجب: ${l.homework}`);
        return `[حصة ${date}] ${parts.join(' - ') || 'بدون تفاصيل مسجّلة'}`;
    }).join('\n')
    : 'لا يوجد سجل حصص سابقة بعد.';

const notesText = notes.length
    ? notes.map(n => `- ${n.note}`).join('\n')
    : 'لا توجد ملاحظات مسجّلة عن هذا الطالب.';

const positionText = [
    student.current_surah ? `السورة الحالية: ${student.current_surah}` : null,
    (student.current_from_ayah && student.current_to_ayah)
        ? `آخر مقطع تم أخذه: من آية ${student.current_from_ayah} إلى آية ${student.current_to_ayah}`
        : null,
    student.current_topic ? `الموضوع الحالي: ${student.current_topic}` : null
].filter(Boolean).join('\n') || 'لا يوجد تسجيل لموضع الطالب الحالي.';

const systemPrompt = `أنت مساعد ذكاء اصطناعي متخصص في مساعدة معلم القرآن الكريم أثناء التحضير للحصة أو أثناءها فعليًا مع الطالب "${student.name}".

مهمتك: تنفيذ طلبات المعلم بدقة (شرح آيات، اقتراح طريقة شرح، إجابة أسئلة تتعلق بالمنهج أو الطالب)، مع مراعاة كل ما يلي:

== بيانات الطالب ==
الاسم: ${student.name}
المادة: ${student.subject || 'غير محددة'}
${positionText}

== سجل آخر الحصص (الأحدث أولاً) ==
${lessonsText}

== ملاحظات المعلم عن هذا الطالب ==
${notesText}

== تعليمات مهمة لأسلوبك ==
1. لو المعلم قال "اشرح الصفحة/المقطع التالي" أو ما شابه من غير ما يحدد آيات بنفسه، اعتمد على "آخر مقطع تم أخذه" في بيانات الطالب فوق كنقطة بداية، واشرح المقطع اللي بعده منطقيًا.
2. اطّلع على ملاحظات المعلم عن أسلوب الطالب المفضل في التعلّم، وفصّل أسلوب شرحك حسبها تلقائيًا من غير ما تسأله: لو الملاحظات بتقول إن الطالب بيحب الأمثلة من الحياة العملية، اربط الشرح بأمثلة واقعية قريبة منه. لو بيحب القصص، ركّز على قصص التفسير وأسباب النزول المرتبطة بالآيات.
3. لو مفيش ملاحظات واضحة عن أسلوب معين، اشرح بأسلوب متوازن وواضح يناسب طالب عادي.
4. ردودك موجّهة للمعلم عشان يستخدمها في شرح الطالب، مش موجّهة للطالب مباشرة.
5. خلّي ردودك مركّزة وعملية، بدون حشو، وبالعربية الفصحى الواضحة إلا لو المعلم كتب بالعامية.
6. لو الطلب غامض جدًا ومحتاج توضيح (مثلاً "اشرح" من غير أي تحديد ومفيش سياق كافي يوضح المقصود)، اسأل سؤال توضيحي واحد قصير بدل ما تفترض حاجة غلط.`;

const contents = memoryItems.map(m => ({
    role: m.role === 'assistant' ? 'model' : 'user',
    parts: [{ text: m.content }]
}));
contents.push({ role: 'user', parts: [{ text: config.message }] });

return {
    teacherId: config.teacherId,
    studentId: config.studentId,
    userMessage: config.message,
    dailyLimit: config.dailyLimit,
    requestCount: $('Reserve Daily Quota').item.json.request_count,
    geminiModel: config.geminiModel,
    geminiRequestBody: {
        systemInstruction: { parts: [{ text: systemPrompt }] },
        contents,
        generationConfig: {
            temperature: 0.7,
            maxOutputTokens: 900
        }
    }
};

const prev = $('Build Gemini Prompt').item.json;
const raw = $input.first().json;

const errorMessages = {
    RATE_LIMITED: 'الخدمة مزدحمة حاليًا (وصلنا للحد المؤقت مع مزوّد الذكاء الاصطناعي)، من فضلك حاول تاني بعد دقيقة.',
    BLOCKED: 'تعذّر توليد رد مناسب لهذا الطلب، جرّب تصيغه بطريقة مختلفة.',
    AI_ERROR: 'حدث خطأ غير متوقع أثناء التواصل مع المساعد الذكي، من فضلك حاول مرة أخرى.'
};

// حالة: فشل استدعاء Gemini بالكامل (خطأ شبكة/مصادقة/تجاوز حد الاستخدام 429 إلخ)
if (raw.error) {
    const errText = JSON.stringify(raw.error).toLowerCase();
    const statusCode = raw.error.httpCode || raw.error.status || raw.error.code || '';
    let errorType = 'AI_ERROR';
    if (String(statusCode).includes('429') || errText.includes('resource_exhausted') || errText.includes('quota')) {
        errorType = 'RATE_LIMITED';
    }
    return {
        success: false,
        errorType,
        message: errorMessages[errorType],
        teacherId: prev.teacherId
    };
}

const candidate = raw.candidates && raw.candidates[0];
const finishReason = candidate && candidate.finishReason;
const text = candidate && candidate.content && candidate.content.parts && candidate.content.parts[0] && candidate.content.parts[0].text;

if (!text) {
    const errorType = (finishReason === 'SAFETY' || finishReason === 'BLOCKLIST' || finishReason === 'PROHIBITED_CONTENT') ? 'BLOCKED' : 'AI_ERROR';
    return {
        success: false,
        errorType,
        message: errorMessages[errorType],
        teacherId: prev.teacherId
    };
}

return {
    success: true,
    reply: text.trim(),
    teacherId: prev.teacherId,
    studentId: prev.studentId,
    userMessage: prev.userMessage,
    dailyLimit: prev.dailyLimit,
    requestCount: prev.requestCount
};

